-- CR-111 follow-up: 12 prompt-this-no-asset defects - rewrite prompt so the
-- item is self-contained and the keyed answer is the only defensible choice
-- (removes answer leaks like "This is green. What color is this?" and adds
-- the missing context for image-dependent prompts).
begin;
update practice.qb_questions set prompt_text='What color is grass?', choices='["Red","Blue","Yellow","Green"]'::jsonb, answer='{"text":"Green","index":3}'::jsonb, explanation_vi='Cỏ có màu xanh lá (green).', content_hash='07629d081e41ba71' where id='g1-english-bulk-0519e86a758e';
update practice.qb_questions set prompt_text='You wave goodbye with this body part. What is it?', choices='["a ball","a book","a hand","a tree"]'::jsonb, answer='{"text":"a hand","index":2}'::jsonb, explanation_vi='Ta vẫy tay chào tạm biệt bằng bàn tay (a hand).', content_hash='e7c844e73068a392' where id='g1-english-bulk-276d447320ef';
update practice.qb_questions set prompt_text='You do this to send a ball to your friend. Which action is it?', choices='["catch","throw","wash","read"]'::jsonb, answer='{"text":"throw","index":1}'::jsonb, explanation_vi='Ném (throw) là hành động đưa bóng cho bạn.', content_hash='0b8cac62d4cca75e' where id='g1-english-bulk-36f2f0693764';
update practice.qb_questions set prompt_text='Mai is crying. What feeling is this?', choices='["Sad","Big","Green","Sing"]'::jsonb, answer='{"text":"Sad","index":0}'::jsonb, explanation_vi='Khóc (crying) cho thấy cảm xúc buồn (sad).', content_hash='a8c2c0722e48bbb6' where id='g1-english-bulk-61a047deafef';
update practice.qb_questions set prompt_text='It is a small red fruit with tiny seeds on the outside. What fruit is it?', choices='["strawberry","blueberry","raspberry","cherry"]'::jsonb, answer='{"text":"strawberry","index":0}'::jsonb, explanation_vi='Dâu tây (strawberry) là quả nhỏ màu đỏ có hạt li ti ở bên ngoài.', content_hash='e6904e1e9f5b0477' where id='g1-english-bulk-62f59bcb8872';
update practice.qb_questions set prompt_text='What number is between six and eight?', choices='["five","six","seven","eight"]'::jsonb, answer='{"text":"seven","index":2}'::jsonb, explanation_vi='Số nằm giữa sáu (six) và tám (eight) là bảy (seven).', content_hash='8488f7f7bc919345' where id='g1-english-bulk-76ad4a8e1860';
update practice.qb_questions set prompt_text='What number is after eight?', choices='["six","seven","eight","nine"]'::jsonb, answer='{"text":"nine","index":3}'::jsonb, explanation_vi='Số đứng sau tám (eight) là chín (nine).', content_hash='4f9466ebe0346010' where id='g1-english-bulk-8818271b2c21';
update practice.qb_questions set prompt_text='This juice is made from carrots. What color is it?', choices='["Purple","White","Orange","Black"]'::jsonb, answer='{"text":"Orange","index":2}'::jsonb, explanation_vi='Nước ép cà rốt có màu cam (orange).', content_hash='fcd00b8de66d7330' where id='g1-english-bulk-a01da14a1b93';
update practice.qb_questions set prompt_text='You do this with a book to know the story. Which action is it?', choices='["eat","sing","cut","read"]'::jsonb, answer='{"text":"read","index":3}'::jsonb, explanation_vi='Đọc (read) là việc ta làm với một quyển sách.', content_hash='6eaa389fd029e0dc' where id='g1-english-bulk-a57176ff54c7';
update practice.qb_questions set prompt_text='Five shirts and five more shirts. Which number is this?', choices='["10","1","9","11"]'::jsonb, answer='{"text":"10","index":0}'::jsonb, explanation_vi='Năm cộng năm bằng mười (10).', content_hash='a8bce105c9b987a1' where id='g1-english-bulk-b28a4b457059';
update practice.qb_questions set prompt_text='Someone says "Hello!" to you. What do you say back?', choices='["Hi","Bye","Good morning","Thank you"]'::jsonb, answer='{"text":"Hi","index":0}'::jsonb, explanation_vi='Khi ai đó chào "Hello!", ta đáp lại "Hi".', content_hash='970feda873cd2853' where id='g1-english-bulk-b3664558ea92';
update practice.qb_questions set prompt_text='It is a story with magic, a princess, and a happy ending. What kind of story is it?', choices='["A funny story.","A scary story.","A fairy tale.","A science fiction story."]'::jsonb, answer='{"text":"A fairy tale.","index":2}'::jsonb, explanation_vi='Truyện có phép màu, công chúa và kết thúc có hậu là truyện cổ tích (a fairy tale).', content_hash='7c3ba09b55db2bd7' where id='g5-english-bulk-f997aded161c';
commit;
